def _softrestaurant_empresa_id_for_window(conn, cfg: Dict[str, Any], fi: str, ff: str) -> str:
    """Resuelve idempresa sin hardcode y falla cerrado ante ambiguedad."""
    configured = _s(cfg.get("empresa_id"))
    if configured:
        return configured

    cur = conn.cursor(as_dict=True)
    cur.execute(
        """
        SELECT DISTINCT
            LTRIM(RTRIM(CONVERT(NVARCHAR(100), t.idempresa))) AS empresa_id
        FROM turnos t WITH (NOLOCK)
        WHERE t.apertura >= %s
          AND t.apertura < %s
          AND t.cierre IS NOT NULL
          AND NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(100), t.idempresa))), '') IS NOT NULL
        ORDER BY empresa_id
        """,
        (fi, ff),
    )
    candidates = sorted({
        _s(row.get("empresa_id"))
        for row in (cur.fetchall() or [])
        if _s(row.get("empresa_id"))
    })
    cur.close()

    if len(candidates) == 1:
        return candidates[0]
    if not candidates:
        raise RuntimeError("SoftRestaurant sin idempresa en turnos cerrados del rango operativo")
    raise RuntimeError("SoftRestaurant con multiples idempresa; configurar empresa_id canonica antes de sincronizar")


